function makerEscape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function renderMakers(id){return `<section class="maker-section"><span class="eyebrow">Manufacturers, sellers & market shares</span><h3>Major companies</h3><p class="maker-note">Representative companies verified through official product and technical sources. List order is not a market ranking. Company and product status checked: October 5, 2026.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Manufacturers and chemistry-specific shares"><table class="maker-table"><thead><tr><th scope="col">Company / official source</th><th scope="col">Role, product & supply status</th><th scope="col">2025 share in this battery category</th></tr></thead><tbody>${MAKERS[id].map(m=>`<tr><th scope="row"><a href="${makerEscape(m[2])}" target="_blank" rel="noopener">${makerEscape(m[0])} ↗</a></th><td>${makerEscape(m[1])}</td><td><span class="unknown-share">Public figure not verified</span></td></tr>`).join('')}</tbody></table></div><p class="maker-note">Comparable 2025 global company shares for this specific chemistry could not be verified. Unverified does not mean 0%. Overall company revenue, production capacity and cumulative installations are not converted into market shares.</p></section>`;}
function renderEVShare(){return `<section class="maker-section ev-reference"><span class="eyebrow">Reference · all EV battery chemistries</span><h3>2025 global EV battery company ranking</h3><p class="maker-note">Battery capacity installed in EVs, PHEVs and HEVs registered in 80 countries from January to December 2025: 1,187 GWh in total. These figures combine LFP, NMC, NCA and other chemistries; their scope differs from chemistry-specific market shares.</p><div class="table-scroll" tabindex="0" role="region" aria-label="2025 EV battery company ranking"><table class="maker-table"><thead><tr><th scope="col">Rank</th><th scope="col">Company</th><th scope="col">Installed capacity</th><th scope="col">Total market share</th></tr></thead><tbody>${EV_SHARE_2025.map((r,i)=>`<tr><td>${i+1}</td><th scope="row">${r[0]}</th><td>${r[2].toFixed(1)} GWh</td><td><span class="share-value">${r[1].toFixed(1)}%</span><span class="share-bar" style="--share:${r[1]}%"></span></td></tr>`).join('')}<tr><td>—</td><th scope="row">Other companies</th><td>124.9 GWh</td><td>10.5%</td></tr></tbody></table></div><p class="maker-note">Rounding may prevent shares from summing to 100%. Rankings use installed capacity, so companies with the same rounded share, such as 3.7% or 2.4%, may have different ranks. This is not a retail revenue or all-battery sales ranking.</p><div class="sources"><a href="https://www.sneresearch.com/kr/insight/release_view/584/page/0?s_cat=%7C&s_keyword=" target="_blank" rel="noopener">SNE Research · Full-year 2025 data (February 4, 2026) ↗</a></div></section>`;}
